    "story": "con- 源自拉丁介词 cum，意为“与、一起”。在古典拉丁语中，它作为前缀常写作 com-，并随后面辅音的发音部位发生同化：在 b、p、m 前作 com-（combine），在 l 前作 col-（collect），在 r 前作 cor-（correct），在元音和 h 前则简化为 co-（cooperate）。这一前缀进入英语后，既表示“共同、一起”，也可起加强语气的作用，是英语中构词能力最强的前缀之一。",
