    "story": "un- 是英语本族语前缀，源自古英语 un-，更早可追溯到原始日耳曼语 *un-，最终来自原始印欧语的否定小词 *n̥-（零级形式）。它与拉丁语 in-、希腊语 a-/an- 同源，但在英语中属于日耳曼遗产，因此几乎可以自由加在形容词、分词和名词前表示否定，如 unhappy、unfair。另一个重要功能是加在动词前表示“做相反动作”，如 undo、unlock、untie，这一用法在古英语中已见。",
