    "story": "re- 源自拉丁语前缀 re-，本义为“向后、往回”，引申为“再次、重新”。它由拉丁语进入法语，再随诺曼征服进入英语，成为英语中最高产的前缀之一。re- 的基本义是“回、再”，如 return（返回）、rebuild（重建）；但在某些词中发展出“反向、反对”的意思，如 reaction（反作用）、resist（抵抗）。由于来源复杂，部分 re- 词已不易拆分，学习时宜按整体词义记忆。",
