    "story": "soph 源自希腊语 sophos，意为“聪明的、有智慧的”，也指“技艺高超的人”。古希腊的“智者派”自称 sophistai，即“有智慧的人”，后来该词在哲学论辩中带上了“诡辩者”的贬义。sophia 表示“智慧”，是哲学（philosophia，即“爱智慧”）一词的核心成分。经拉丁语和法语传入英语后，soph 成为表示智慧、思辨与老练的词根，构成 philosophy、sophisticated、sophistry 等词。",
