    "pie": false,
    "story": "with- 源自古英语介词 wið，本义为“对抗、相反、反对”，与德语 wider（反对）同源。在中古英语时期，with 逐渐获得“和……一起”的伴随义，但作为构词前缀的 with- 仍保留古义，表示“向后、离开、对抗”。因此 withdraw 是“向后拉”即撤回，withstand 是“站在对立面”即抵抗，withhold 是“扣住不给”。这一前缀属于日耳曼语本土成分，与拉丁语前缀 re-、contra- 在功能上相近。",
