    "story": "-itis 源自希腊语形容词后缀 -itēs，本义为“属于……的”。在古希腊医学中，医师用阴性形式 -itis 构成疾病名称，尤其指炎症，如 arthritis（关节炎）、bronchitis（支气管炎）。这一用法经拉丁语和法语进入英语，成为医学英语中表示“炎症”的能产后缀，可加于器官或组织名词之后，如 appendicitis（阑尾炎）、dermatitis（皮炎）。它几乎专用于病理名称。",
