    "story": "kal 源自希腊语形容词 kalos，意为“美的、美丽的”，其变体 kallos 为名词“美”。该词可追溯至原始印欧语词根 *kal-（美、健康）。经由拉丁语和法语进入英语后，kal 成为表示“美”的构词成分，常见于 kaleidoscope（万花筒，原义为“观察美丽的形状”）、calligraphy（书法，原义为“美丽的书写”）、callisthenics（健美操）等词中。变体 calli 多见于复合词。",
